import React, { useState } from "react";
import { FaBars, FaTimes } from "react-icons/fa";
import Nav from './component/nav';
import Artikel from './settings/artikel';
import Corousel from './settings/corousel';
import Penghargaan from './settings/penghargaan';
import Video from './settings/video';
import Pmb from './settings/infopmb';

const Settings = () => {
  const [page, setPage] = useState("Artikel");  // Set default page as "Artikel"
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);  // Sidebar open state
  
  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  return (
    <div className="flex flex-col h-screen bg-teal-100 font-sans">
      {/* Header */}
      <header className="bg-teal-200 text-teal-800 px-6 py-4 flex justify-between items-center shadow">
        <h1 className="text-xl font-bold">Admin Panel</h1>
        <div className="flex items-center">
          <span className="material-icons text-3xl mr-2">account_circle</span>
        </div>
        {/* Toggle Sidebar Button */}
        <button onClick={toggleSidebar} className="text-3xl">
          {isSidebarOpen ? <FaTimes /> : <FaBars />}
        </button>
      </header>

      {/* Container */}
      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <Nav isSidebarOpen={isSidebarOpen} />

        {/* Main Content */}
        <main className="flex-1 bg-teal-50 p-6 overflow-y-auto">
          <h2 className="text-6xl font-bold mb-4">Settings</h2>

          {/* Filter Status Chat */}
          <div>
            <ul className="flex mb-4">
              {["Artikel", "Corousel", "Penghargaan", "Video", "PMB"].map((item) => (
                <li
                  key={item}
                  className={`mr-4 p-2 rounded-lg cursor-pointer ${page === item ? "bg-teal-700 text-white" : "bg-teal-500"}`}
                >
                  <button onClick={() => setPage(item)}>
                    {item.charAt(0).toUpperCase() + item.slice(1)}
                  </button>
                </li>
              ))}
            </ul>
          </div>

          {/* Konten Tabel */}
          <div className="">
            {page === "Artikel" && <Artikel />}
            {page === "Corousel" && <Corousel />}
            {page === "Penghargaan" && <Penghargaan />}
            {page === "Video" && <Video />}
            {page === "PMB" && <Pmb />}
          </div>
        </main>
      </div>
    </div>
  );
};

export default Settings;
